  VALUES
    ('FTH-R-001', 'Roomy five-tab horizontal baseline', 'Five cards fill the rail without empty trailing space.', '/design-system/canonical-renderings/floating-tab-header/FTH-R-001', '/design-system/components/floating-tab-header?ref=FTH-R-001&tabs=5&layout=horizontal&subTabs=off&attention=off&expandable=off&categorySwitch=on&theme=normal&dir=ltr&zoom=0', 'Desktop full-width rail', 1440, 'normal', 'ltr', 0, 'five-tab-baseline', '{"query":"tabs=5&layout=horizontal&subTabs=off&attention=off&expandable=off&categorySwitch=on&theme=normal&dir=ltr&zoom=0"}'::jsonb, 10, TRUE),
    ('FTH-R-002', 'Crowded ten-tab compact baseline', 'Ten tabs use compact cards without hidden-count summaries.', '/design-system/canonical-renderings/floating-tab-header/FTH-R-002', '/design-system/components/floating-tab-header?ref=FTH-R-002&tabs=10&layout=horizontal&subTabs=off&attention=off&expandable=off&categorySwitch=on&theme=normal&dir=ltr&zoom=0', 'Desktop single-row crowded rail', 1440, 'normal', 'ltr', 0, 'ten-tab-compact', '{"query":"tabs=10&layout=horizontal&subTabs=off&attention=off&expandable=off&categorySwitch=on&theme=normal&dir=ltr&zoom=0"}'::jsonb, 20, TRUE),
