    ('FTH-R-016', 'RTL horizontal', 'Control column, arrows, summaries, and drawer anchoring mirror.', '/design-system/canonical-renderings/floating-tab-header/FTH-R-016', '/design-system/components/floating-tab-header?ref=FTH-R-016&tabs=12&layout=horizontal&subTabs=on&attention=on&expandable=on&categorySwitch=on&theme=normal&dir=rtl&zoom=0', 'Desktop RTL horizontal', 1440, 'normal', 'rtl', 0, 'rtl-horizontal', '{"query":"tabs=12&layout=horizontal&subTabs=on&attention=on&expandable=on&categorySwitch=on&theme=normal&dir=rtl&zoom=0"}'::jsonb, 160, FALSE),
    ('FTH-R-017', 'Magnified horizontal', 'Magnification keeps text contained without overlapping hidden counts.', '/design-system/canonical-renderings/floating-tab-header/FTH-R-017', '/design-system/components/floating-tab-header?ref=FTH-R-017&tabs=12&layout=horizontal&subTabs=on&attention=on&expandable=on&categorySwitch=on&theme=normal&dir=ltr&zoom=100', 'Tablet magnified horizontal', 1024, 'normal', 'ltr', 100, 'magnified-horizontal', '{"query":"tabs=12&layout=horizontal&subTabs=on&attention=on&expandable=on&categorySwitch=on&theme=normal&dir=ltr&zoom=100"}'::jsonb, 170, FALSE),
